// Golden test: the planning sheets fed with the Excel v5 sample inputs and the v5 BOQ (template only,
// no calculators) must reproduce the values Excel cached in Man-Day_Basic, S-Curve_Plan_Basic and
// CashFLOW_Basic (golden.planning.v5.json, generated by scripts/excel/extract-planning-golden.mjs).
// Where decision D1 changes a value, the new value is asserted and the reason is written next to it.
import { describe, expect, it } from 'vitest';
import { computeBoq } from '../../boq/engine';
import { BOQ_TEMPLATE_V5 } from '../../boq/template.v5';
import type { BoqItemRow } from '../../boq/types';
import { computePlanning, defaultPlanningInput, isoToSerial, PLAN_TASKS } from '..';
import golden from './golden.planning.v5.json';

type Cell = number | string | null;
interface GoldenBlock { O: Cell; P: Cell; Q: Cell; R: Cell; S: Cell; T: Cell; U: Cell }
interface GoldenTask {
    row: number; no: string; name: string; D: Cell; E: Cell; F: Cell; G: Cell; H: Cell; grid: Cell[];
    actual: { D: Cell; E: Cell; F: Cell; G: Cell; H: Cell; grid: Cell[] };
}
interface GoldenCfRow { A: Cell; B: Cell; C: Cell; Y: Cell; Z: Cell; weeks: Cell[] }

const g = golden as unknown as {
    manday: Record<string, GoldenBlock>; T310: number; U310: number;
    scurve: {
        D5: number; D6: number; D7: number; Q4: number; Q5: number; Q6: number; Q7: string;
        row9: number[]; tasks: GoldenTask[];
        row86: Cell[]; row87: Cell[]; row88: Cell[]; row89: Cell[]; row90: Cell[]; row91: Cell[]; row92: Cell[]; row93: Cell[];
    };
    cashflow: { D2: number; K2: number; dash: Record<string, number>; rows: Record<string, GoldenCfRow> };
};

/** Excel "" (no overlap) is 0 in the app. */
const n = (c: Cell): number => (typeof c === 'number' ? c : 0);

/**
 * The dump prints cached values with 10 significant digits, so compare relatively:
 * |actual − expected| ≤ 1e-9 × max(1, |expected|). `close(actual, label, expected)` or `close(actual, expected)`.
 */
function close(actual: number | null | undefined, labelOrExpected: string | number, maybeExpected?: number): void {
    const label = typeof labelOrExpected === 'string' ? labelOrExpected : '';
    const expected = typeof labelOrExpected === 'number' ? labelOrExpected : (maybeExpected ?? NaN);
    expect(actual, `${label} is null`).not.toBeNull();
    expect(actual, `${label} is undefined`).not.toBeUndefined();
    const a = actual ?? NaN;
    expect(Math.abs(a - expected), `${label}: ${a} vs Excel ${expected}`)
        .toBeLessThanOrEqual(1e-9 * Math.max(1, Math.abs(expected)));
}

/**
 * Baht amounts built from many grid cells: Excel adds 1E-12 to every non-empty weekly share
 * (`MAX(0, share+1E-12)`), which the app does not; × ฿2.1 M over ≤ 60 cells that stays below 0.001 baht.
 */
function money(actual: number | null | undefined, label: string, expected: number): void {
    const a = actual ?? NaN;
    expect(Math.abs(a - expected), `${label}: ${a} vs Excel ${expected}`)
        .toBeLessThanOrEqual(Math.max(1e-3, 1e-9 * Math.abs(expected)));
}

const boq = computeBoq({ sections: BOQ_TEMPLATE_V5 });
const result = computePlanning(defaultPlanningInput(), boq);
const { manday, schedule, cashflow } = result;

const block = (id: string) => {
    const b = manday.blocks.find(x => x.id === id);
    if (!b) throw new Error(`block ${id} missing`);
    return b;
};
const sectionRows = (no: number) =>
    (boq.sections.find(s => s.no === no)?.rows ?? []).filter((r): r is BoqItemRow => r.type === 'item');

/**
 * Blocks whose calculated days S differ from Excel (decision D1, BOQ engine sums every row):
 * Excel's K95 / K216 labour sub-totals skip the embedded waste-pipe rows 84–86 (section 9) and the
 * water-pipe rows 213–214 (section 21), so Excel's S82 / S209 ignore that labour; the app includes it.
 */
const D1_LABOUR_ROWS: Record<string, { section: number; rows: number[] }> = {
    '2.1': { section: 9, rows: [84, 85, 86] },
    '6.3': { section: 21, rows: [213, 214] },
};

describe('Man-Day_Basic (planning columns O..U)', () => {
    it('has the 32 blocks of the Excel, in order', () => {
        expect(manday.blocks.map(b => b.excelRow)).toEqual(Object.keys(g.manday).map(Number));
    });

    it.each(PLAN_TASKS.map(t => [t.id, t.manday.excelRow] as const))('task %s ← block row %i matches Excel', (id, row) => {
        const x = g.manday[String(row)];
        if (!x) throw new Error(`golden row ${row} missing`);
        const b = block(id);
        expect(b.skilled).toBe(n(x.O));
        expect(b.labourers).toBe(n(x.P));
        expect(b.crew).toBe(n(x.Q));
        expect(b.dailyWage).toBe(n(x.R));
        expect(b.days).toBe(n(x.T));
        close(b.budget, n(x.U));
        if (x.S === null) {
            expect(b.calcDays).toBeNull();          // piles: S34 has no formula
            return;
        }
        const d1 = D1_LABOUR_ROWS[id];
        if (!d1) {
            close(b.calcDays, n(x.S));
            return;
        }
        // D1: S = (Excel labour + the pipe rows' labour) ÷ R.
        const extra = sectionRows(d1.section).filter(r => d1.rows.includes(r.excelRow)).reduce((s, r) => s + r.labTotal, 0);
        expect(extra).toBeGreaterThan(0);
        close(b.calcDays, n(x.S) + extra / b.dailyWage);
    });

    it('D1 effect on S82 / S209 (sections 9 and 21): exact values', () => {
        // Excel S82 = 14,576.595 / 3,300 = 4.41715; the app adds waste-pipe labour K84:K86.
        close(block('2.1').boqLabour, sectionRows(9).reduce((s, r) => s + r.labTotal, 0));
        close(block('2.1').calcDays, block('2.1').boqLabour / 3300);
        expect(block('2.1').suggestedDays).toBe(Math.round(block('2.1').boqLabour / 3300));
        // Excel S209 = 12,395 / 2,600 = 4.767; the app adds water-pipe labour K213:K214.
        close(block('6.3').calcDays, block('6.3').boqLabour / 2600);
    });

    it('T310 รวมเวลา = 164 and U310 รวมงบประมาณ = 1,850,317.34', () => {
        expect(manday.totalDays).toBe(g.T310);
        expect(manday.totalDays).toBe(164);
        close(manday.totalBudget, g.U310);
        close(manday.totalBudget, boq.constructionTotal);
    });

    it('split blocks read the Excel row ranges (ก่ออิฐ 179–183 / 184–186, ฉาบปูน 189–191 / 192–196)', () => {
        close(block('4.1').budget + block('4.2').budget, boq.sections[17]?.total ?? NaN);
        close(block('5.1').budget + block('5.2').budget, boq.sections[18]?.total ?? NaN);
        close(block('4.2').budget, 29351.565);
        close(block('5.2').budget, 46451.49);
    });

    it('20 %-of-total rule for aluminium (24) and เบ็ดเตล็ด (28)', () => {
        close(block('7.1').labourCost, 99277.5 * 0.2);
        close(block('8.3').labourCost, 28400 * 0.2);
    });
});

describe('S-Curve_Plan_Basic', () => {
    const iso = (c: Cell) => (typeof c === 'number' ? c : null);
    const serial = (s: string | null) => isoToSerial(s);

    it('header KPIs D5 / D6 / D7', () => {
        expect(serial(schedule.start)).toBe(g.scurve.D5);
        expect(serial(schedule.finish)).toBe(g.scurve.D6);
        close(schedule.budget, g.scurve.D7);
        expect(schedule.durationDays).toBe(142);
    });

    it('week axis = Excel row 9 (48 buckets: 12 months × W1..W4)', () => {
        expect(schedule.buckets.map(b => b.startSerial)).toEqual(g.scurve.row9);
        expect(schedule.buckets[0]?.monthLabel).toBe('ม.ค.-26');
        expect(schedule.buckets[47]?.monthLabel).toBe('ธ.ค.-26');
        expect(schedule.buckets.slice(0, 4).map(b => b.days)).toEqual([7, 8, 7, 9]);
    });

    it.each(g.scurve.tasks.map(t => [t.no, t] as const))('task %s: D/E/F/G/H and weekly plan match Excel', (no, x) => {
        const t = schedule.tasks.find(y => y.id === no);
        if (!t) throw new Error(`task ${no} missing`);
        expect(t.name).toBe(x.name.trim());
        expect(t.duration).toBe(n(x.D));
        expect(serial(t.start)).toBe(iso(x.E));
        expect(serial(t.finish)).toBe(iso(x.F));
        close(t.budget, n(x.G));
        close(t.weight, n(x.H));
        expect(t.plan).toHaveLength(48);
        t.plan.forEach((v, i) => { close(v, `bucket ${i}`, n(x.grid[i] ?? null)); });
    });

    it('task 4.2 duration is the typed 4 (not linked); task 1.1 budget = section 2 total (BOQ M17)', () => {
        const t42 = schedule.tasks.find(t => t.id === '4.2');
        expect(t42?.duration).toBe(4);
        expect(t42?.durationFromManDay).toBe(false);
        expect(schedule.tasks.find(t => t.id === '1.1')?.budget).toBe(boq.sections[2]?.total);
    });

    it('ACTUAL row 15 (task 1.1): F, H and the weekly actual share', () => {
        const x = g.scurve.tasks[0];
        const t = schedule.tasks[0];
        if (!x || !t) throw new Error('task 1.1 missing');
        expect(serial(t.actual.finish)).toBe(iso(x.actual.F));
        close(t.actual.weight, n(x.actual.H));
        t.actual.weekly.forEach((v, i) => { close(v, n(x.actual.grid[i] ?? null)); });
    });

    it('summary rows 86/87 (plan % per week, cumulative) and 90/91 (actual)', () => {
        schedule.planWeekly.forEach((v, i) => { close(v, `86[${i}]`, n(g.scurve.row86[i] ?? null)); });
        schedule.planCumulative.forEach((v, i) => { close(v, `87[${i}]`, n(g.scurve.row87[i] ?? null)); });
        schedule.actualWeekly.forEach((v, i) => { close(v, `90[${i}]`, n(g.scurve.row90[i] ?? null)); });
        schedule.actualCumulative.forEach((v, i) => { close(v, `91[${i}]`, n(g.scurve.row91[i] ?? null)); });
        close(schedule.planCumulative[19], 1);   // AC87 = 100 % at May W4
    });

    it('rows 88/89 (plan cost per month, cumulative) and 92/93 (actual)', () => {
        expect(schedule.months).toHaveLength(12);
        for (const m of schedule.months) {
            const col = m.firstBucket;
            close(m.planCost, m.label, n(g.scurve.row88[col] ?? null));
            close(m.planCumulativeCost, m.label, n(g.scurve.row89[col] ?? null));
            close(m.actualCost, m.label, n(g.scurve.row92[col] ?? null));
            close(m.actualCumulativeCost, m.label, n(g.scurve.row93[col] ?? null));
        }
        expect(schedule.months.slice(0, 5).map(m => Math.round(m.planCost))).toEqual([325764, 423319, 382662, 283602, 434971]);
    });

    it('status Q4 last update, Q5 earned value, Q6 spent, Q7 delay text', () => {
        expect(serial(schedule.status.lastUpdate)).toBe(g.scurve.Q4);
        close(schedule.status.earnedValue, g.scurve.Q5);
        close(schedule.status.spent, g.scurve.Q6);
        expect(schedule.status.delayText).toBe(g.scurve.Q7);
        expect(schedule.status.delayDays).toBe(0);
        expect(schedule.status.delayStatus).toBe('onTime');
    });

    it('installment groups carry their tasks and budgets', () => {
        expect(schedule.installments.map(i => i.taskIds.length)).toEqual([7, 5, 3, 2, 2, 5, 2, 6]);
        close(schedule.installments.reduce((s, i) => s + i.weight, 0), 1);
    });
});

describe('CashFLOW_Basic', () => {
    const row = (r: number) => {
        const x = g.cashflow.rows[String(r)];
        if (!x) throw new Error(`golden cash-flow row ${r} missing`);
        return x;
    };
    const weeks = (r: number) => row(r).weeks.map(n);
    const expectRow = (actual: number[], r: number, asMoney = false) => {
        expect(actual).toHaveLength(20);
        actual.forEach((v, i) => { (asMoney ? money : close)(v, `row ${r}[${i}]`, weeks(r)[i] ?? NaN); });
    };

    it('D2 construction cost and K2 quotation = cost × 1.3', () => {
        close(cashflow.cost, g.cashflow.D2);
        close(cashflow.quotation, g.cashflow.K2);
    });

    it('axis = first 20 S-Curve buckets (Jan–May 2026)', () => {
        expect(cashflow.buckets).toHaveLength(20);
        expect(cashflow.months.map(m => m.label)).toEqual(['ม.ค.-26', 'ก.พ.-26', 'มี.ค.-26', 'เม.ย.-26', 'พ.ค.-26']);
    });

    it('installments rows 6–14: amount = % × K2 in the sample weeks', () => {
        expect(cashflow.installments).toHaveLength(9);
        cashflow.installments.forEach((inst, i) => {
            const r = 6 + i;
            expect(inst.pct).toBe(row(r).B);
            expect(inst.label).toBe(String(row(r).C).trim());
            expectRow(inst.weekly, r);
        });
        close(cashflow.installmentPctTotal, 1);
    });

    it('rows 15–18: weekly income, outflow, net and cumulative Cash FLOW', () => {
        expectRow(cashflow.incomeWeekly, 15);
        expectRow(cashflow.outflowWeekly, 16, true);
        expectRow(cashflow.netWeekly, 17, true);
        expectRow(cashflow.cumulative, 18, true);
        expect(cashflow.minCumulative?.bucket).toBe(14);   // column R (Mar W3)
        money(cashflow.minCumulative?.value, 'min R18', -115556.1054);
        money(cashflow.cumulative[19], 'W18', 277547.6014);
        // The cash position ends at quotation − cost × 1.15 = 15 % of the cost.
        close(cashflow.cumulative[19], cashflow.cost * 0.15);
    });

    it('rows 21–52: weekly plan share per task; B group shares', () => {
        cashflow.tasks.forEach((t, i) => {
            const r = 21 + i;
            expect(t.name).toBe(String(row(r).C).trim());
            expectRow(t.weekly, r);
        });
        const groupRows = [21, 28, 33, 36, 38, 40, 45, 47];
        cashflow.groups.forEach((grp, i) => { close(grp.share, n(row(groupRows[i] ?? 0).B)); });
    });

    it('rows 54–59: plan %, cost, 15 % operating cost, cost + opex, 15 % profit', () => {
        expectRow(cashflow.planPctWeekly, 54);
        expectRow(cashflow.costWeekly, 55, true);
        expectRow(cashflow.opexWeekly, 56, true);
        expectRow(cashflow.outflowWeekly, 57, true);
        expectRow(cashflow.profitWeekly, 59, true);
    });

    it('Finance Dashboard (EVM)', () => {
        const d = g.cashflow.dash;
        const e = cashflow.evm;
        expect(e.duration).toBe(d.AA2);
        close(e.bac, d.AA4 ?? NaN);
        money(e.pv, 'AA6 PV', d.AA6 ?? NaN);
        money(e.ev, 'Z19 EV', d.Z19 ?? NaN);
        expect(e.ac).toBe(d.Z18);
        money(e.sv, 'AA7 SV', d.AA7 ?? NaN);
        money(e.cv, 'AA8 CV', d.AA8 ?? NaN);
        close(e.spi, d.AA9 ?? NaN);
        close(e.cpi, d.AA10 ?? NaN);
        close(e.eacDays, d.AA11 ?? NaN);
        money(e.eacCost, 'AA12 EAC', d.AA12 ?? NaN);
        money(e.vac, 'AA13 VAC', d.AA13 ?? NaN);
        money(e.profitPlan, 'AA14', d.AA14 ?? NaN);
        money(e.profitForecast, 'AA15', d.AA15 ?? NaN);
        cashflow.tasks.forEach((t, i) => {
            const r = 21 + i;
            expect(t.progress).toBe(row(r).Y);
            money(t.earnedValue, `Z${r}`, n(row(r).Z));
        });
    });
});
